!function() {
    var docEl = document.documentElement;
    docEl.classList.remove("no-js");
    docEl.classList.add("js");

    if (document.body.classList.contains("has-animations") && typeof ScrollReveal !== "undefined") {
        var sr = ScrollReveal();

        sr.reveal(".hero-title, .hero-paragraph, .hero-cta", {
            delay: 150,
            duration: 1000,
            distance: "60px",
            easing: "cubic-bezier(0.215, 0.61, 0.355, 1)",
            origin: "bottom",
            interval: 150
        });

        sr.reveal(".hero-right-decoration", {
            duration: 1000,
            distance: "40px",
            easing: "cubic-bezier(0.215, 0.61, 0.355, 1)",
            origin: "top"
        });

        sr.reveal(".hero-left-decoration", {
            duration: 1000,
            distance: "40px",
            easing: "cubic-bezier(0.215, 0.61, 0.355, 1)",
            origin: "bottom"
        });

        sr.reveal(".feature, .pricing-table, .pricing-faqs, .cta-inner", {
            duration: 600,
            distance: "40px",
            easing: "cubic-bezier(0.215, 0.61, 0.355, 1)",
            interval: 100,
            origin: "bottom",
            viewFactor: 0.2
        });
    }

    var accordions = document.getElementsByClassName("accordion-title");
    for (var i = 0; i < accordions.length; i++) {
        accordions[i].addEventListener("click", function() {
            var parent = this.parentNode;
            parent.classList.toggle("is-open");
            var body = this.nextElementSibling;
            if (body.style.maxHeight) {
                body.style.maxHeight = null;
            } else {
                body.style.maxHeight = body.scrollHeight + "px";
            }
        });
    }

    var tabLinks = document.getElementsByClassName("tab-link");
    for (var j = 0; j < tabLinks.length; j++) {
        tabLinks[j].addEventListener("click", function(e) {
            e.preventDefault();

            var container = this.closest(".tabs-container");
            if (!container) return;

            var links = container.getElementsByClassName("tab-link");
            var panels = container.nextElementSibling.getElementsByClassName("tab-panel");

            for (var k = 0; k < links.length; k++) {
                links[k].classList.remove("is-active");
            }

            for (var m = 0; m < panels.length; m++) {
                panels[m].classList.remove("is-active");
            }

            this.classList.add("is-active");

            var targetId = this.getAttribute("href");
            var targetPanel = document.querySelector(targetId);
            if (targetPanel) {
                targetPanel.classList.add("is-active");
            }
        });
    }

    var containers = document.getElementsByClassName("tabs-container");
    for (var n = 0; n < containers.length; n++) {
        var firstLink = containers[n].getElementsByClassName("tab-link")[0];
        if (firstLink) {
            firstLink.classList.add("is-active");
            var firstTarget = document.querySelector(firstLink.getAttribute("href"));
            if (firstTarget) {
                firstTarget.classList.add("is-active");
            }
        }
    }
}();